const { fitDataAsync, OPTIMIZERS } = DataScience;
const { vec } = NMath;
const components = 50;

// Use the same MNIST sample set and 50-component PCA as the compression example.
const samples = await IO.loadMNIST();
const pca = PCA.new(samples, components);
const targets = samples.map(sample => vec(...pca.proj(sample)));
const randomImage = () => Float32Array.from({ length: 28 * 28 }, () => Math.random());

// A projected random image and a digit define a straight path and its velocity.
const training = targets.flatMap(target => Array.from({ length: 2 }, () => {
    const source = vec(...pca.proj(randomImage()));
    const t = Math.random();
    return {
        input: vec(...source.scale(1 - t).add(target.scale(t)).components, t),
        velocity: target.sub(source),
    };
}));

// Predict all 50 PCA-space velocity components with one symbolic network.
const field = NeuralNet.builder()
    .input(components + 1)
    .layer(64)
    .layer(64)
    .layer(components, NeuralNet.ACTIVATIONS.linear)
    .build();
const { theta } = await fitDataAsync(
    training.map(sample => sample.input),
    training.map(sample => sample.velocity),
    field.model,
    {
        epochs: 3000,
        batch: 100,
        optimizer: OPTIMIZERS.ADAMW({
            learningRate: 0.005,
            beta1: 0.9,
            beta2: 0.99,
            weightDecay: 0.01,
        }),
        continuationEvery: 100,
        continuationFn: ({ epoch, loss }) => console.log(`Epoch ${epoch + 1}, loss ${loss.toFixed(4)}`),
    },
);
field.setWeights(theta);

const steps = 100;
let time = 0;
let trajectory;
const image = IO.paintMNIST(new Float32Array(28 * 28));
const showTime = () => {
    if (!trajectory) return;
    // PCA reconstruction can exceed the display range.
    const pixels = pca.gen(trajectory[Math.round(time * steps)].components).toArray();
    image.update(Float32Array.from(pixels, value => Math.max(0, Math.min(1, value))));
};

const drawing = IO.drawMNIST({
    randomButton: true,
    onSubmit: data => {
        // Cache Euler steps from the submitted image so the slider can move both ways.
        trajectory = [vec(...pca.proj(data))];
        for (let step = 0; step < steps; step++) {
            const point = trajectory[step];
            const velocity = vec(...field.eval(vec(...point.components, step / steps)));
            trajectory.push(point.add(velocity.scale(1 / steps)));
        }
        showTime();
    },
});

const ui = IO.UI(
    { type: "canvas", value: () => drawing },
    { type: "canvas", value: () => image },
    {
        type: "slider", value: () => ({
            title: "t:", min: 0, max: 1, step: 1 / steps, value: 0,
            onChange: value => { time = value; showTime(); },
        })
    },
);
ui;
